/**
 * Reset-to-provided button handler.
 *
 * Generic across steps that support reset (4 / 5 / 9). The button must have
 * id="resetButton" on the page. Behaviour is preserved verbatim from the
 * v2.9.0 implementation that previously lived in cdcf_bootstrap.js: opens a
 * Bootstrap SAVE_CANCEL modal, POSTs FormData to the reset endpoint via fetch,
 * reloads on success, alerts on failure.
 *
 * Lang strings are passed pre-resolved from PHP via cfg.resetLang to avoid an
 * extra core/str round-trip when the modal opens.
 *
 * Expected cfg shape:
 *   {
 *       cmid:     int,
 *       step:     int,
 *       groupid:  int,
 *       sesskey:  string,
 *       resetUrl: string,
 *       resetLang: {
 *           modalTitle:   string,
 *           modalBody:    string,
 *           modalConfirm: string,
 *           genericError: string
 *       }
 *   }
 *
 * @module     mod_gestionprojet/reset_button
 * @copyright  2026 Emmanuel REMY
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(["core/modal_save_cancel","core/modal_events","core/notification"],(function(e,t,n){"use strict";return{init:function(o){var r=document.getElementById("resetButton");r&&o&&o.resetUrl&&r.addEventListener("click",(function(){var r,a=o.resetLang||{};e.create({title:a.modalTitle,body:"<p>"+(r=a.modalBody,String(null==r?"":r).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")+"</p>"),large:!1}).then((function(e){return e.setSaveButtonText(a.modalConfirm),e.getRoot().on(t.save,(function(t){t.preventDefault();var n=e.getRoot().find('[data-action="save"]');n.prop("disabled",!0);var r=new FormData;r.append("id",o.cmid),r.append("step",o.step),r.append("groupid",o.groupid||0),r.append("sesskey",o.sesskey),fetch(o.resetUrl,{method:"POST",credentials:"same-origin",body:r}).then((function(e){return e.json().then((function(t){return{ok:e.ok,body:t}}))})).then((function(t){if(e.hide(),t.ok&&t.body.success){var o=window.location.href.split("#")[0],r=o.indexOf("?")>-1?"&":"?";window.location.href=o+r+"_resetts="+Date.now()}else window.alert(t.body&&t.body.message||a.genericError),n.prop("disabled",!1)})).catch((function(){e.hide(),window.alert(a.genericError)}))})),e.show(),e})).catch(n.exception)}))}}}));